script.source:
return ['_doc': ctx.payload.hits.hits.stream().map(
        v -> {v.get('_source').put('index', v.get('_index'));
        v.remove('_index');
        v.remove('_type');
        v.get('_source').put('threat.detection', ctx.watch_id);
        v.get('_source').put('event.timestamp_detected', ctx.trigger.triggered_time);
        v.get('_source').put('threat.is_alert', true);
        v.get('_source').put('threat.alert_type', 'Detection of cryptocurrency-related activity');
        v.get('_source').put('threat.detection_description', 'AWS Guardduty detects alerts querying an IP Address or domain that is associated with Bitcoin or other cryptocurrency-related activity.');
        v.get('_source').put('threat.severity', 'medium');
        v.get('_source').put('threat.triage_score', 40);
        v.get('_source').put('threat.ratingtime_sla_applies', 'true');
        v.get('_source').put('id', v.get('_id'));
        return v.get('_source')}).collect(Collectors.toList())]
